import re


def unique_slug(title, existing):
    base = re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-") or "item"
    if base not in existing:
        return base
    suffix = 2
    while f"{base}-{suffix}" in existing:
        suffix += 1
    return f"{base}-{suffix}"

